using System.Data;
using Microsoft.EntityFrameworkCore;
using Sace.Api.Contracts;
using Sace.Api.Domain;
using Sace.Api.Infrastructure;

namespace Sace.Api.Services;

public interface IImmexInventoryImportService { Task<IReadOnlyList<ImmexInventoryEntry>> ImportOperationAsync(Guid operationId,Guid userId,CancellationToken ct=default); }
public interface IImmexDischargeEngine {
  Task<ImmexDischargePreviewDto> PreviewAsync(ImmexExitRequest request,CancellationToken ct=default);
  Task<ImmexInventoryExit> ConfirmAsync(ImmexExitRequest request,Guid userId,CancellationToken ct=default);
  Task<ImmexDischargeReversal> ReverseAsync(Guid dischargeId,string reason,Guid userId,CancellationToken ct=default);
}
public interface IImmexTemporalityService {
  Task<ImmexTemporalityResultDto> CalculateAsync(ImmexInventoryEntry entry,DateTime evaluationDate,CancellationToken ct=default);
  Task<int> RecalculateAsync(Guid? programId,DateTime evaluationDate,Guid userId,CancellationToken ct=default);
}
public interface IImmexInventoryReconciliationService { Task<IReadOnlyList<ImmexInventoryIssue>> ReconcileAsync(Guid programId,Guid userId,CancellationToken ct=default); }

public class ImmexTemporalityService(SaceDbContext db,IConfiguration configuration) : IImmexTemporalityService {
  public async Task<ImmexTemporalityResultDto> CalculateAsync(ImmexInventoryEntry entry,DateTime evaluationDate,CancellationToken ct=default){
    if(entry.AvailableQuantity<=0)return new(null,entry.TemporalityRuleCode,entry.TemporalityRuleVersion,null,null,null,entry.DueDate,ImmexTemporalityOutcome.RESOLVED,"HIGH","Saldo completamente descargado; la temporalidad se considera resuelta.",null);
    var rules=await db.ImmexTemporalityRules.AsNoTracking().Where(x=>x.InventoryClassification==entry.InventoryClassification&&x.Status==SourceVerificationStatus.VERIFIED&&x.OfficialSourceCitationId!=null&&x.EffectiveFrom<=entry.EntryDate&&(x.EffectiveTo==null||x.EffectiveTo>=entry.EntryDate)).OrderByDescending(x=>x.IsOverride).ThenByDescending(x=>x.Priority).ThenByDescending(x=>x.Version).ToListAsync(ct);
    var rule=rules.FirstOrDefault(x=>Matches(x,entry));
    if(rule is null)return new(null,null,null,null,null,null,null,ImmexTemporalityOutcome.MANUAL_REVIEW,"LOW","No existe una regla VERIFIED inequívoca para la clasificación y fecha de entrada.",null);
    if(rule.RequiresManualQualification)return new(rule.Id,rule.Code,rule.Version,rule.DurationType,rule.DurationValue,rule.DurationUnit,null,ImmexTemporalityOutcome.MANUAL_REVIEW,"MEDIUM","La regla requiere calificación manual antes de calcular vencimiento.",rule.OfficialSourceCitationId);
    DateTime? due=rule.DurationType switch { ImmexDurationType.FIXED_PERIOD when rule.DurationValue.HasValue&&rule.DurationUnit==ImmexDurationUnit.MONTH=>entry.EntryDate.AddMonths(rule.DurationValue.Value), ImmexDurationType.FIXED_PERIOD when rule.DurationValue.HasValue&&rule.DurationUnit==ImmexDurationUnit.YEAR=>entry.EntryDate.AddYears(rule.DurationValue.Value), ImmexDurationType.FIXED_PERIOD when rule.DurationValue.HasValue&&rule.DurationUnit==ImmexDurationUnit.DAY=>entry.EntryDate.AddDays(rule.DurationValue.Value), ImmexDurationType.PROGRAM_VALIDITY=>await db.ImmexPrograms.Where(x=>x.Id==entry.ImmexProgramId).Select(x=>x.ValidTo).SingleAsync(ct), _=>null };
    if(rule.DurationType==ImmexDurationType.NOT_APPLICABLE)return new(rule.Id,rule.Code,rule.Version,rule.DurationType,rule.DurationValue,rule.DurationUnit,null,ImmexTemporalityOutcome.NOT_APPLICABLE,"HIGH","La regla aplicable indica que no existe plazo calculable.",rule.OfficialSourceCitationId);
    if(due is null)return new(rule.Id,rule.Code,rule.Version,rule.DurationType,rule.DurationValue,rule.DurationUnit,null,ImmexTemporalityOutcome.INSUFFICIENT_DATA,"LOW","La regla no permite calcular una fecha sin información adicional del programa.",rule.OfficialSourceCitationId);
    var days=(due.Value.Date-evaluationDate.Date).Days;var soon=configuration.GetValue("ImmexInventory:DueSoonDays",90);var critical=configuration.GetValue("ImmexInventory:CriticalDays",30);var outcome=days<0?ImmexTemporalityOutcome.PAST_DUE:days<=critical?ImmexTemporalityOutcome.DUE_CRITICAL:days<=soon?ImmexTemporalityOutcome.DUE_SOON:ImmexTemporalityOutcome.ACTIVE;
    return new(rule.Id,rule.Code,rule.Version,rule.DurationType,rule.DurationValue,rule.DurationUnit,due,outcome,"HIGH",$"Regla {rule.Code} v{rule.Version}; quedan {Math.Max(0,days)} días calendario{(days<0?$"; vencida hace {-days} días":"")}.",rule.OfficialSourceCitationId);
  }
  public async Task<int> RecalculateAsync(Guid? programId,DateTime evaluationDate,Guid userId,CancellationToken ct=default){
    var query=db.ImmexInventoryEntries.Where(x=>!programId.HasValue||x.ImmexProgramId==programId);var entries=await query.ToListAsync(ct);foreach(var entry in entries){var result=await CalculateAsync(entry,evaluationDate,ct);entry.TemporalRuleId=result.RuleId;entry.TemporalityRuleCode=result.RuleCode;entry.TemporalityRuleVersion=result.RuleVersion;entry.DueDate=result.DueDate;entry.TemporalityOutcome=result.Outcome;entry.TemporalityCalculatedAt=DateTime.UtcNow;entry.TemporalityExplanation=result.Explanation;entry.UpdatedAt=DateTime.UtcNow;if(entry.AvailableQuantity<=0)entry.Status=ImmexInventoryEntryStatus.DISCHARGED;else if(result.Outcome==ImmexTemporalityOutcome.PAST_DUE)entry.Status=ImmexInventoryEntryStatus.PAST_DUE;else if(entry.Status==ImmexInventoryEntryStatus.PAST_DUE)entry.Status=entry.AvailableQuantity<entry.OriginalQuantity?ImmexInventoryEntryStatus.PARTIALLY_DISCHARGED:ImmexInventoryEntryStatus.OPEN;}
    db.SystemAuditLogs.Add(Log(userId,"IMMEX_TEMPORALITY_CALCULATED",nameof(ImmexInventoryEntry),programId?.ToString()??"ALL",$"{entries.Count} entradas evaluadas al {evaluationDate:yyyy-MM-dd}."));await db.SaveChangesAsync(ct);return entries.Count;
  }
  static bool Matches(ImmexTemporalityRule rule,ImmexInventoryEntry entry){if(string.IsNullOrWhiteSpace(rule.ConditionsJson)||rule.ConditionsJson=="{}")return true;try{using var doc=System.Text.Json.JsonDocument.Parse(rule.ConditionsJson);var root=doc.RootElement;if(root.TryGetProperty("tariffFraction",out var tariff)&&tariff.GetString()!=entry.TariffFraction)return false;if(root.TryGetProperty("nico",out var nico)&&nico.GetString()!=entry.Nico)return false;return true;}catch(System.Text.Json.JsonException){return false;}}
  static SystemAuditLog Log(Guid user,string action,string entity,string id,string details)=>new(){UserId=user==Guid.Empty?null:user,Action=action,EntityType=entity,EntityId=id,Details=details};
}

public class ImmexDischargeEngine(SaceDbContext db) : IImmexDischargeEngine {
  public async Task<ImmexDischargePreviewDto> PreviewAsync(ImmexExitRequest request,CancellationToken ct=default)=>await BuildPreview(request,ct);
  public async Task<ImmexInventoryExit> ConfirmAsync(ImmexExitRequest request,Guid userId,CancellationToken ct=default){
    await using var tx=await db.Database.BeginTransactionAsync(IsolationLevel.Serializable,ct);try{
      var preview=await BuildPreview(request,ct);if(preview.Outcome is ImmexDischargeOutcome.UNIT_CONVERSION_REQUIRED or ImmexDischargeOutcome.MANUAL_REVIEW)throw new InvalidOperationException(preview.Outcome.ToString());
      var exit=new ImmexInventoryExit{ImmexProgramId=request.ImmexProgramId,TradeOperationId=request.TradeOperationId,ExitType=request.ExitType,PedimentoNumber=Clean(request.PedimentoNumber),PedimentoKey=Clean(request.PedimentoKey),ExitDate=request.ExitDate,ProductId=request.ProductId,MaterialId=request.MaterialId,Quantity=request.Quantity,Unit=Unit(request.Unit),TariffFraction=Tariff(request.TariffFraction),Nico=Clean(request.Nico),Reference=Clean(request.Reference),AllocatedQuantity=preview.AllocatedQuantity,UnallocatedQuantity=preview.UnallocatedQuantity,DischargeOutcome=preview.Outcome};db.ImmexInventoryExits.Add(exit);
      var sequence=0;foreach(var allocation in preview.Allocations){var entry=await db.ImmexInventoryEntries.SingleAsync(x=>x.Id==allocation.EntryId,ct);if(entry.AvailableQuantity!=allocation.EntryBalanceBefore||entry.AvailableQuantity<allocation.Quantity)throw new DbUpdateConcurrencyException("INVENTORY_BALANCE_CHANGED");entry.AvailableQuantity=allocation.EntryBalanceAfter;entry.Status=entry.AvailableQuantity==0?ImmexInventoryEntryStatus.DISCHARGED:ImmexInventoryEntryStatus.PARTIALLY_DISCHARGED;entry.TemporalityOutcome=entry.AvailableQuantity==0?ImmexTemporalityOutcome.RESOLVED:entry.TemporalityOutcome;entry.UpdatedAt=DateTime.UtcNow;exit.Discharges.Add(new(){InventoryEntryId=entry.Id,MaterialId=entry.MaterialId!.Value,Sequence=++sequence,QuantityDischarged=allocation.Quantity,Unit=allocation.Unit,EntryBalanceBefore=allocation.EntryBalanceBefore,EntryBalanceAfter=allocation.EntryBalanceAfter,Explanation=$"PEPS por cantidad: lote {entry.PedimentoNumber}, fecha {entry.EntryDate:yyyy-MM-dd}."});}
      if(preview.UnallocatedQuantity>0){var issue=new ImmexInventoryIssue{ImmexProgramId=request.ImmexProgramId,InventoryExit=exit,IssueCode="UNALLOCATED_QUANTITY",Severity=ImmexIssueSeverity.HIGH,Description=$"Cantidad sin asignar: {preview.UnallocatedQuantity:0.######} {preview.Unit}."};db.ImmexInventoryIssues.Add(issue);db.SystemAuditLogs.Add(Log(userId,"IMMEX_ISSUE_CREATED",nameof(ImmexInventoryIssue),issue.Id,$"{issue.IssueCode}: {issue.Description}"));}
      db.SystemAuditLogs.Add(Log(userId,"IMMEX_DISCHARGE_CREATED",nameof(ImmexInventoryExit),exit.Id,$"PEPS: {preview.AllocatedQuantity:0.######} asignado; {preview.UnallocatedQuantity:0.######} sin asignar."));await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return await db.ImmexInventoryExits.AsNoTracking().Include(x=>x.Discharges).SingleAsync(x=>x.Id==exit.Id,ct);
    }catch{await tx.RollbackAsync(ct);throw;}
  }
  public async Task<ImmexDischargeReversal> ReverseAsync(Guid dischargeId,string reason,Guid userId,CancellationToken ct=default){
    if(string.IsNullOrWhiteSpace(reason))throw new InvalidOperationException("La razón de reversión es obligatoria.");await using var tx=await db.Database.BeginTransactionAsync(IsolationLevel.Serializable,ct);try{var discharge=await db.ImmexInventoryDischarges.Include(x=>x.Reversal).Include(x=>x.InventoryEntry).Include(x=>x.InventoryExit).SingleOrDefaultAsync(x=>x.Id==dischargeId,ct)??throw new KeyNotFoundException("EXIT_NOT_FOUND");if(discharge.Reversal is not null)throw new InvalidOperationException("DISCHARGE_ALREADY_REVERSED");discharge.InventoryEntry.AvailableQuantity+=discharge.QuantityDischarged;if(discharge.InventoryEntry.AvailableQuantity>discharge.InventoryEntry.OriginalQuantity)throw new InvalidOperationException("REVERSAL_EXCEEDS_ORIGINAL_QUANTITY");discharge.InventoryEntry.Status=discharge.InventoryEntry.AvailableQuantity==discharge.InventoryEntry.OriginalQuantity?ImmexInventoryEntryStatus.OPEN:ImmexInventoryEntryStatus.PARTIALLY_DISCHARGED;discharge.InventoryEntry.UpdatedAt=DateTime.UtcNow;discharge.InventoryExit.AllocatedQuantity-=discharge.QuantityDischarged;discharge.InventoryExit.UnallocatedQuantity+=discharge.QuantityDischarged;discharge.InventoryExit.DischargeOutcome=ImmexDischargeOutcome.PARTIALLY_ALLOCATED;var reversal=new ImmexDischargeReversal{OriginalDischargeId=discharge.Id,Reason=reason.Trim(),ReversedBy=userId};db.ImmexDischargeReversals.Add(reversal);db.SystemAuditLogs.Add(Log(userId,"IMMEX_DISCHARGE_REVERSED",nameof(ImmexInventoryDischarge),discharge.Id,reason.Trim()));await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return reversal;}catch{await tx.RollbackAsync(ct);throw;}
  }
  async Task<ImmexDischargePreviewDto> BuildPreview(ImmexExitRequest request,CancellationToken ct){
    if(request.Quantity<=0)throw new InvalidOperationException("INVALID_DISCHARGE");if(!request.MaterialId.HasValue)return new(ImmexDischargeOutcome.MANUAL_REVIEW,request.Quantity,0,request.Quantity,Unit(request.Unit),[],"Se requiere MaterialId para un matching inequívoco.");
    var entries=await db.ImmexInventoryEntries.AsNoTracking().Where(x=>x.ImmexProgramId==request.ImmexProgramId&&x.MaterialId==request.MaterialId&&x.AvailableQuantity>0&&x.InventoryClassification!=ImmexInventoryClassification.FIXED_ASSET&&x.Status!=ImmexInventoryEntryStatus.DISCHARGED).OrderBy(x=>x.EntryDate).ThenBy(x=>x.Sequence).ThenBy(x=>x.Id).ToListAsync(ct);if(entries.Count==0)return new(ImmexDischargeOutcome.INSUFFICIENT_INVENTORY,request.Quantity,0,request.Quantity,Unit(request.Unit),[],"No existe inventario elegible para la salida.");
    var targetUnit=Unit(entries[0].TigieUnit);if(entries.Any(x=>Unit(x.TigieUnit)!=targetUnit))return new(ImmexDischargeOutcome.MANUAL_REVIEW,request.Quantity,0,request.Quantity,Unit(request.Unit),[],"Las entradas elegibles utilizan unidades distintas.");var requested=request.Quantity;var exitUnit=Unit(request.Unit);if(exitUnit!=targetUnit){var conversion=await db.ImmexUnitConversions.AsNoTracking().Where(x=>x.MaterialId==request.MaterialId&&x.FromUnit==exitUnit&&x.ToUnit==targetUnit&&x.IsVerified&&x.EffectiveFrom<=request.ExitDate&&(x.EffectiveTo==null||x.EffectiveTo>=request.ExitDate)).OrderByDescending(x=>x.EffectiveFrom).FirstOrDefaultAsync(ct);if(conversion is null)return new(ImmexDischargeOutcome.UNIT_CONVERSION_REQUIRED,request.Quantity,0,request.Quantity,exitUnit,[],"Las unidades no coinciden y no existe una conversión verificada.");requested=decimal.Round(request.Quantity*conversion.Factor,9,MidpointRounding.AwayFromZero);}
    var remaining=requested;var allocations=new List<ImmexDischargeAllocationDto>();foreach(var entry in entries){if(remaining<=0)break;var quantity=Math.Min(entry.AvailableQuantity,remaining);allocations.Add(new(entry.Id,entry.PedimentoNumber,entry.EntryDate,entry.AvailableQuantity,quantity,entry.AvailableQuantity-quantity,targetUnit));remaining-=quantity;}
    var allocated=requested-remaining;var outcome=remaining==0?ImmexDischargeOutcome.ALLOCATED:allocated>0?ImmexDischargeOutcome.PARTIALLY_ALLOCATED:ImmexDischargeOutcome.INSUFFICIENT_INVENTORY;return new(outcome,requested,allocated,remaining,targetUnit,allocations,remaining==0?"Asignación PEPS completa.":$"Inventario insuficiente; quedan {remaining:0.######} {targetUnit} sin asignar.");
  }
  static string Unit(string value)=>value.Trim().ToUpperInvariant();static string? Clean(string? value)=>string.IsNullOrWhiteSpace(value)?null:value.Trim();static string? Tariff(string? value)=>string.IsNullOrWhiteSpace(value)?null:new string(value.Where(char.IsDigit).ToArray()).PadLeft(8,'0');
  static SystemAuditLog Log(Guid user,string action,string entity,Guid id,string details)=>new(){UserId=user==Guid.Empty?null:user,Action=action,EntityType=entity,EntityId=id.ToString(),Details=details};
}

public class ImmexInventoryImportService(SaceDbContext db,IImmexTemporalityService temporality) : IImmexInventoryImportService {
  public async Task<IReadOnlyList<ImmexInventoryEntry>> ImportOperationAsync(Guid operationId,Guid userId,CancellationToken ct=default){
    var operation=await db.TradeOperations.Include(x=>x.Documents).ThenInclude(x=>x.Fields).SingleOrDefaultAsync(x=>x.Id==operationId,ct)??throw new KeyNotFoundException("OPERATION_NOT_FOUND");if(!operation.ImmexProgramId.HasValue||operation.IsTemporaryImport!=true)throw new InvalidOperationException("IMMEX_TEMPORARY_EVIDENCE_REQUIRED");
    var existing=await db.ImmexInventoryEntries.Where(x=>x.TradeOperationId==operationId).OrderBy(x=>x.Sequence).ToListAsync(ct);if(existing.Count>0)return existing;
    var fields=operation.Documents.SelectMany(x=>x.Fields.Select(f=>new{Document=x,Field=f})).ToList();var sequences=fields.Where(x=>x.Field.Sequence.HasValue).Select(x=>x.Field.Sequence!.Value).Distinct().Order().ToList();if(sequences.Count==0)sequences.Add(1);var created=new List<ImmexInventoryEntry>();
    foreach(var sequence in sequences){string? Value(string code)=>fields.Where(x=>(x.Field.Sequence??1)==sequence&&x.Field.FieldCode==code).OrderByDescending(x=>x.Field.IsManuallyConfirmed).Select(x=>x.Field.NormalizedValue??x.Field.RawValue).FirstOrDefault();var quantity=Decimal(Value(DocumentFieldCodes.Quantity))??operation.Quantity;var unit=Value(DocumentFieldCodes.Unit)??operation.Unit;var tariff=Value(DocumentFieldCodes.TariffFraction)??operation.TariffFraction;var part=Value("MATERIAL_CODE")??Value("PART_NUMBER");var material=string.IsNullOrWhiteSpace(part)?null:await db.ImmexMaterials.FirstOrDefaultAsync(x=>x.ImmexProgramId==operation.ImmexProgramId&&x.MaterialCode==part,ct);var manual=quantity is null||quantity<=0||string.IsNullOrWhiteSpace(unit)||string.IsNullOrWhiteSpace(tariff)||material is null;var entry=new ImmexInventoryEntry{ImmexProgramId=operation.ImmexProgramId.Value,TradeOperationId=operation.Id,OperationDocumentId=fields.FirstOrDefault(x=>(x.Field.Sequence??1)==sequence)?.Document.Id,MaterialId=material?.Id,PedimentoNumber=operation.PedimentoNumber,PedimentoKey=operation.PedimentoKey,PedimentoItemNumber=sequence,Sequence=sequence,EntryDate=operation.OperationDate,CustomsOffice=operation.CustomsOffice,TariffFraction=NormalizeTariff(tariff),Nico=Value(DocumentFieldCodes.Nico)??operation.Nico,PartNumber=part,Description=Value(DocumentFieldCodes.Description)??operation.GoodsDescription??"Descripción pendiente de confirmar",OriginalQuantity=Math.Max(0,quantity??0),AvailableQuantity=Math.Max(0,quantity??0),TigieUnit=Unit(unit??"PENDIENTE"),CommercialValue=operation.CommercialValue,Currency=operation.Currency,InventoryClassification=ImmexInventoryClassification.OTHER,Status=manual?ImmexInventoryEntryStatus.MANUAL_REVIEW:ImmexInventoryEntryStatus.OPEN};db.ImmexInventoryEntries.Add(entry);created.Add(entry);}
    await db.SaveChangesAsync(ct);foreach(var entry in created){var result=await temporality.CalculateAsync(entry,DateTime.UtcNow.Date,ct);entry.TemporalRuleId=result.RuleId;entry.TemporalityRuleCode=result.RuleCode;entry.TemporalityRuleVersion=result.RuleVersion;entry.DueDate=result.DueDate;entry.TemporalityOutcome=result.Outcome;entry.TemporalityCalculatedAt=DateTime.UtcNow;entry.TemporalityExplanation=result.Explanation;db.SystemAuditLogs.Add(Log(userId,"IMMEX_ENTRY_CREATED",nameof(ImmexInventoryEntry),entry.Id,$"Entrada {entry.PedimentoNumber}; secuencia {entry.Sequence}."));}db.SystemAuditLogs.Add(Log(userId,"IMMEX_ENTRY_IMPORTED",nameof(TradeOperation),operation.Id,$"{created.Count} partida(s) importadas al inventario IMMEX."));await db.SaveChangesAsync(ct);return created;
  }
  static decimal? Decimal(string? value)=>decimal.TryParse(value,System.Globalization.NumberStyles.Any,System.Globalization.CultureInfo.InvariantCulture,out var n)?n:null;static string Unit(string value)=>value.Trim().ToUpperInvariant();static string NormalizeTariff(string value){var digits=new string(value.Where(char.IsDigit).ToArray());return digits.Length<=8?digits.PadLeft(8,'0'):digits[..8];}static SystemAuditLog Log(Guid user,string action,string entity,Guid id,string details)=>new(){UserId=user==Guid.Empty?null:user,Action=action,EntityType=entity,EntityId=id.ToString(),Details=details};
}

public class ImmexInventoryReconciliationService(SaceDbContext db) : IImmexInventoryReconciliationService {
  public async Task<IReadOnlyList<ImmexInventoryIssue>> ReconcileAsync(Guid programId,Guid userId,CancellationToken ct=default){
    if(!await db.ImmexPrograms.AnyAsync(x=>x.Id==programId,ct))throw new KeyNotFoundException("IMMEX_PROGRAM_NOT_FOUND");var issues=new List<ImmexInventoryIssue>();var entries=await db.ImmexInventoryEntries.AsNoTracking().Where(x=>x.ImmexProgramId==programId).ToListAsync(ct);var entryIds=entries.Select(x=>x.Id).ToList();var discharged=await db.ImmexInventoryDischarges.AsNoTracking().Where(x=>entryIds.Contains(x.InventoryEntryId)&&x.Reversal==null).GroupBy(x=>x.InventoryEntryId).Select(x=>new{x.Key,Quantity=x.Sum(y=>y.QuantityDischarged)}).ToDictionaryAsync(x=>x.Key,x=>x.Quantity,ct);
    foreach(var entry in entries){var expected=entry.OriginalQuantity-discharged.GetValueOrDefault(entry.Id);if(entry.AvailableQuantity<0)issues.Add(Issue(programId,entry.Id,null,"NEGATIVE_BALANCE",ImmexIssueSeverity.CRITICAL,"El saldo persistido es negativo."));if(expected!=entry.AvailableQuantity)issues.Add(Issue(programId,entry.Id,null,"QUANTITY_INCONSISTENCY",ImmexIssueSeverity.HIGH,$"Esperado {expected:0.######}; persistido {entry.AvailableQuantity:0.######}."));}
    var exits=await db.ImmexInventoryExits.AsNoTracking().Where(x=>x.ImmexProgramId==programId).ToListAsync(ct);foreach(var exit in exits.Where(x=>x.AllocatedQuantity==0&&x.Quantity>0))issues.Add(Issue(programId,null,exit.Id,"ORPHAN_EXIT",ImmexIssueSeverity.HIGH,"Salida sin entrada elegible."));
    var open=await db.ImmexInventoryIssues.Where(x=>x.ImmexProgramId==programId&&x.Status==ImmexIssueStatus.OPEN).Select(x=>new{x.IssueCode,x.InventoryEntryId,x.InventoryExitId}).ToListAsync(ct);var added=issues.Where(x=>!open.Any(o=>o.IssueCode==x.IssueCode&&o.InventoryEntryId==x.InventoryEntryId&&o.InventoryExitId==x.InventoryExitId)).ToList();db.ImmexInventoryIssues.AddRange(added);foreach(var issue in added)db.SystemAuditLogs.Add(Log(userId,"IMMEX_ISSUE_CREATED",nameof(ImmexInventoryIssue),issue.Id,$"{issue.IssueCode}: {issue.Description}"));db.SystemAuditLogs.Add(Log(userId,"IMMEX_RECONCILIATION_COMPLETED",nameof(ImmexProgram),programId,$"{added.Count} inconsistencia(s) nueva(s); no se modificaron cantidades."));await db.SaveChangesAsync(ct);return added;
  }
  static ImmexInventoryIssue Issue(Guid program,Guid? entry,Guid? exit,string code,ImmexIssueSeverity severity,string description)=>new(){ImmexProgramId=program,InventoryEntryId=entry,InventoryExitId=exit,IssueCode=code,Severity=severity,Description=description};static SystemAuditLog Log(Guid user,string action,string entity,Guid id,string details)=>new(){UserId=user==Guid.Empty?null:user,Action=action,EntityType=entity,EntityId=id.ToString(),Details=details};
}
